        "path": "src/service/ArticleService.ts",
        "content": "import { Service, Autowired } from 'koatty';
import { ArticleModel } from '../model/ArticleModel';
import { CreateArticleDto, UpdateArticleDto, QueryArticleDto } from '../dto/ArticleDto';

@Service()
export class ArticleService {
  @Autowired()
  private articleModel: ArticleModel;

  /**
   * 分页查询
   */
  async findAll(query: QueryArticleDto) {
    const { page = 1, pageSize = 10, ...filters } = query;
    const [list, total] = await ArticleModel.findAndCount({
      where: filters as any,
      skip: (page - 1) * pageSize,
      take: pageSize,
      order: { id: 'DESC' },
    });
    return { list, total, page, pageSize };
  }

  /**
   * 根据 ID 查询
   */
  async findById(id: number) {
    return ArticleModel.findOneBy({ id });
  }

  /**
   * 创建
   */
  async create(dto: CreateArticleDto) {
    const entity = ArticleModel.create(dto as any);
    return ArticleModel.save(entity);
  }

  /**
   * 更新
   */
  async update(id: number, dto: UpdateArticleDto) {
    await ArticleModel.update(id, dto as any);
    return ArticleModel.findOneBy({ id });
  }

  /**
   * 删除
   */
  async delete(id: number) {
    return ArticleModel.delete(id);
  }

}
