        "content": "import { Controller, GetMapping, PostMapping, PutMapping, DeleteMapping, PathVariable, RequestBody, Query as QueryParam, Autowired, KoattyContext } from 'koatty';
import { Validated } from 'koatty_validation';
import { ArticleService } from '../service/ArticleService';
import { CreateArticleDto, UpdateArticleDto, QueryArticleDto } from '../dto/ArticleDto';

@Controller('/article')
export class ArticleController {
  @Autowired()
  private articleService: ArticleService;

  ctx: KoattyContext;

  constructor(ctx: KoattyContext) {
    this.ctx = ctx;
  }

  /**
   * 分页列表
   */
  @GetMapping('/')
  async list(@QueryParam() query: QueryArticleDto) {
    const data = await this.articleService.findAll(query);
    return this.ok(data);
  }

  /**
   * 详情
   */
  @GetMapping('/:id')
  async detail(@PathVariable('id') id: number) {
    const data = await this.articleService.findById(id);
    return this.ok(data);
  }

  /**
   * 创建
   */
  @PostMapping('/')
  @Validated()
  async create(@RequestBody() dto: CreateArticleDto) {
    const data = await this.articleService.create(dto);
    return this.ok(data);
  }

  /**
   * 更新
   */
  @PutMapping('/:id')
  @Validated()
  async update(
    @PathVariable('id') id: number,
    @RequestBody() dto: UpdateArticleDto
  ) {
    const data = await this.articleService.update(id, dto);
    return this.ok(data);
  }

  /**
   * 删除
   */
  @DeleteMapping('/:id')
  async remove(@PathVariable('id') id: number) {
    await this.articleService.delete(id);
    return this.ok();
  }
}
